class Solution:
    def findInteger(self, k: int, digit1: int, digit2: int) -> int:
        limit = 2 ** 31 - 1
        m = k
        while m <= limit:
            if m > k and set(map(int, str(m))) <= {digit1, digit2}:
                return m
            m += k
        return -1

