class Solution {
public:
    int findInteger(int k, int digit1, int digit2) {
        long long limit = INT_MAX;
        for (long long m = k; m <= limit; m += k) {
            if (m <= k) continue;
            long long t = m;
            bool ok = true;
            while (t > 0) {
                int d = t % 10;
                if (d != digit1 && d != digit2) { ok = false; break; }
                t /= 10;
            }
            if (ok) return (int)m;
        }
        return -1;
    }
};

