class Solution {
    public int findInteger(int k, int digit1, int digit2) {
        long limit = Integer.MAX_VALUE;
        TreeSet<Integer> digits = new TreeSet<>();
        digits.add(digit1);
        digits.add(digit2);
        Deque<Long> q = new ArrayDeque<>();
        for (int d : digits)
            if (d > 0) q.offer((long) d);
        while (!q.isEmpty()) {
            long x = q.poll();
            if (x > k && x % k == 0) return (int) x;
            for (int d : digits) {
                long nx = x * 10 + d;
                if (nx <= limit) q.offer(nx);
            }
        }
        return -1;
    }
}

